package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import java.io.*;import java.security.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Unique immutable fsynced files; only an explicitly returned URI gets a temporary read grant. */
final class SleepSummaryFiles {
 static final int MAX_BYTES=1024*1024,MAX_FILES=32;private static final Object LOCK=new Object();private static volatile long historyEpoch;
 static File directory(Context context)throws IOException{File cache=context.getCacheDir().getCanonicalFile(),lexical=new File(cache,"shared-sleep-summaries").getAbsoluteFile(),root=lexical.getCanonicalFile();if(!root.equals(lexical)||!cache.equals(root.getParentFile())||!root.isDirectory()&&!root.mkdirs())throw new IOException("Summary storage unavailable.");return root;}
 static final class Snapshot {final File file;final String sha;final SleepSummary.Data data;final long epoch;volatile boolean shared;Snapshot(File file,String sha,SleepSummary.Data data,long epoch){this.file=file;this.sha=sha;this.data=data;this.epoch=epoch;}Uri uri(Context app){if(!current(epoch))throw new IllegalStateException("Sleep history changed. Prepare a new summary.");return androidx.core.content.FileProvider.getUriForFile(app,app.getPackageName()+".sleep-summary",file);}void discard(){if(!shared||!current(epoch))file.delete();}void verify(BooleanSupplier active)throws Exception{if(!current(epoch)||!active.getAsBoolean())throw new IOException("Sleep history changed. Prepare a new summary.");long age=System.currentTimeMillis()-file.lastModified();if(!file.isFile()||file.length()!=data.bytes.length||age<0||age>SleepSummaryFileProvider.AGE)throw new IOException("This reviewed summary expired. Prepare it again.");MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream input=new FileInputStream(file)){byte[] bytes=new byte[8192];for(int n;(n=input.read(bytes))!=-1;){if(!current(epoch)||!active.getAsBoolean())throw new IOException("Sharing cancelled because sleep history changed or this request ended.");count+=n;if(count>data.bytes.length)throw new IOException("The reviewed summary changed.");hash.update(bytes,0,n);}}if(!current(epoch)||!active.getAsBoolean()||count!=data.bytes.length||!NightAudioArchive.hash(hash.digest()).equals(sha))throw new IOException("The reviewed summary changed. Prepare it again.");}}
 static Snapshot stage(Context app,SleepSummary.Data data,long expectedEpoch,BooleanSupplier active)throws Exception{if(data.bytes.length>MAX_BYTES)throw new IOException("The summary exceeds 1 MiB. Choose a shorter period.");synchronized(LOCK){if(!current(expectedEpoch)||!active.getAsBoolean())throw new IOException("Sleep history changed. Prepare a new summary.");File root=directory(app);File[] old=root.listFiles();if(old==null||old.length>MAX_FILES*2)throw new IOException("Summary cache needs attention. Try again after old documents expire.");int count=0;long now=System.currentTimeMillis();for(File file:old){if(!file.isFile()||!file.getCanonicalFile().equals(file.getAbsoluteFile())||!file.getParentFile().getCanonicalFile().equals(root))throw new IOException("Summary cache unavailable.");if(file.getName().matches("(summary|pending)-[0-9a-f-]{36}\\.json")){if(now-file.lastModified()>SleepSummaryFileProvider.AGE){if(!file.delete())throw new IOException("Expired summary could not be removed.");}else count++;}else throw new IOException("Summary cache contains an unknown entry.");}if(count>=MAX_FILES)throw new IOException("32 recent summaries are already staged. They expire after 24 hours; existing client documents were kept.");File temporary=new File(root,"pending-"+UUID.randomUUID()+".json"),target=new File(root,"summary-"+UUID.randomUUID()+".json");boolean saved=false;try{try(FileOutputStream output=new FileOutputStream(temporary)){for(int at=0;at<data.bytes.length;at+=8192){if(!current(expectedEpoch)||!active.getAsBoolean())throw new IOException("Summary preparation cancelled because sleep history changed or this request ended.");output.write(data.bytes,at,Math.min(8192,data.bytes.length-at));}output.getFD().sync();}if(!current(expectedEpoch)||!active.getAsBoolean())throw new IOException("Summary preparation cancelled because sleep history changed or this request ended.");if(!temporary.renameTo(target))throw new IOException("Summary could not be staged.");saved=true;return new Snapshot(target,NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(data.bytes)),data,expectedEpoch);}finally{temporary.delete();if(!saved)target.delete();}}}
 static long epoch(){return historyEpoch;}
 static boolean current(long expected){return historyEpoch==expected;}
 /** Call before history replacement/removal and again after successful commit. Invalidates even on cleanup failure. */
 static void historyChanging(Context context){synchronized(LOCK){historyEpoch=Math.addExact(historyEpoch,1);RecordAccessGrants.historyChanging(context);AlarmAccessGrants.historyChanging(context);RecordedRecognitionStore.historyChanging(context);try{File root=directory(context);File[] files=root.listFiles();if(files==null||files.length>MAX_FILES*2)throw new IOException("Summary cache cleanup exceeds its bounded limit.");boolean failed=false;for(File file:files){if(!file.getName().matches("(summary|pending)-[0-9a-f-]{36}\\.json"))continue;File absolute=file.getAbsoluteFile(),canonical=file.getCanonicalFile();if(!canonical.equals(absolute)||!root.equals(canonical.getParentFile())||!file.isFile())continue;if(file.getName().startsWith("summary-")){try{Uri uri=androidx.core.content.FileProvider.getUriForFile(context,context.getPackageName()+".sleep-summary",file);context.revokeUriPermission(uri,android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(RuntimeException unavailable){failed=true;}}if(!file.delete()&&file.exists())failed=true;}if(failed)throw new IOException("Generated summary grants or files could not be fully removed.");}catch(IOException failure){throw new IllegalStateException("Summary sharing was invalidated, but local summary cleanup failed. Try deleting history again.",failure);}}}
 static void markShared(Snapshot snapshot){synchronized(LOCK){if(snapshot==null||!current(snapshot.epoch)||!snapshot.file.isFile())throw new IllegalStateException("Sleep history changed. Prepare a new summary.");snapshot.shared=true;}}
 private SleepSummaryFiles(){}
}
